import {debounce} from '@github/mini-throttle'
import {repositoryCheckPath} from '@github-ui/paths'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useCallback, useMemo, useState} from 'react'

export interface RepoCheckResult {
  status: 'checking' | 'complete' | 'error' | 'none'
  hasImmutableReleases?: boolean
}

interface RepoName {
  owner: string
  name: string
}

/**
 * This hook returns 2 pieces:
 * 1. The result of the repo check ('none' if not run yet)
 * 2. A function to run the check on demand (and debounced)
 */
type ReturnType = [RepoCheckResult, (repoName: RepoName) => void]

/**
 * A hook that returns an object with information for additional client-side
 * messaging based on the proposed name. Currently only used to check if a
 * repository has immutable releases, but can be extended.
 */
export function useCheckProposedRepoRestrictions(): ReturnType {
  const [result, setResult] = useState<RepoCheckResult>({status: 'none'})

  const fetchCheck = useCallback(async ({name, owner}: RepoName) => {
    setResult({status: 'checking'})

    try {
      const response = await verifiedFetchJSON(repositoryCheckPath(), {
        method: 'POST',
        body: {owner, name},
      })

      if (!response.ok) {
        setResult({status: 'error'})
        return
      }

      const data = await response.json()
      setResult({
        status: 'complete',
        hasImmutableReleases: data.immutableReleases,
      })
    } catch {
      setResult({status: 'error'})
    }
  }, [])

  const debouncedFetchCheck = useMemo(() => debounce(fetchCheck, 300), [fetchCheck])

  const runCheck = useCallback(
    (repoName: RepoName) => {
      if (!repoName.name || !repoName.owner) {
        setResult({status: 'none'})
        return
      }

      debouncedFetchCheck(repoName)
    },
    [debouncedFetchCheck],
  )

  return [result, runCheck]
}
