import {repositoryCheckNamePath} from '@github-ui/paths'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {useEffect, useEffectEvent, useState} from 'react'

export interface CheckResult {
  status: 'ok' | 'reworded' | 'error' | 'not_found' | 'none'
  repo?: string
  errors?: string
}

/**
 * A hook to check whether the repo name is valid when it changes.
 *
 * The check fires on a 300 ms debounce after `name` or `owner` change. When
 * inputs change again, any pending debounce timer is cleared and any in-flight
 * fetch is aborted, preventing a stale response from overwriting newer state.
 */
export function useCheckRepoName(
  name: string,
  owner: string | undefined,
  onValidityChange: ({valid, invalidReason}: {valid: boolean; invalidReason?: string}) => void,
): CheckResult {
  const [result, setResult] = useState<CheckResult>({status: 'none'})

  // `useEffectEvent` gives the effect below stable handles on the latest
  // closures without invalidating the effect or its debounce timer.
  const resetAndReportInvalid = useEffectEvent((invalidReason: string) => {
    setResult({status: 'none'})
    onValidityChange({valid: false, invalidReason})
  })

  const runFetch = useEffectEvent(async (currentName: string, currentOwner: string, signal: AbortSignal) => {
    const formData = new FormData()
    formData.set('value', currentName)
    formData.set('owner', currentOwner)
    formData.set('json_response', 'true')

    let status: CheckResult['status']
    let invalidReason: string | undefined

    try {
      const response = await verifiedFetch(repositoryCheckNamePath(), {
        method: 'POST',
        body: formData,
        signal,
      })
      if (signal.aborted) return
      const body = await response.json()
      if (signal.aborted) return
      const repo = body.repo
      const errors = body.errors
      if (response.status === 404) {
        status = 'not_found'
        setResult({status})
      } else if (!response.ok) {
        status = 'error'
        invalidReason = getErrorReason(errors)
        setResult({status, repo, errors})
      } else {
        setResult({status: repo === currentName ? 'ok' : 'reworded', repo})
        onValidityChange({valid: true})
        return
      }
    } catch (err) {
      if (signal.aborted || (err instanceof DOMException && err.name === 'AbortError')) return
      status = 'error'
      setResult({status})
    }

    onValidityChange({valid: false, invalidReason: invalidReason ?? status})
  })

  useEffect(() => {
    if (!name) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- intentional: clear stale result + report invalid when inputs change
      resetAndReportInvalid('empty')
      return
    }

    resetAndReportInvalid('none')

    if (!owner) return

    const controller = new AbortController()
    const timer = setTimeout(() => {
      runFetch(name, owner, controller.signal)
    }, 300)

    return () => {
      clearTimeout(timer)
      controller.abort()
    }
  }, [name, owner])

  return result
}

function getErrorReason(errors?: string): string {
  if (!errors) {
    return 'unknown_error'
  }

  if (errors.startsWith('is too long')) {
    return 'too_long'
  }

  if (errors.startsWith('already exists')) {
    return 'in_use'
  }

  return 'unknown_error'
}
