import {ControlGroup} from '@github-ui/control-group'

export function SelectSha256Toggle({
  useSha256,
  onUseSha256Change,
}: {
  useSha256: boolean
  onUseSha256Change: (newVal: boolean) => void
}) {
  return (
    <ControlGroup>
      <ControlGroup.Item>
        <ControlGroup.Title className="fgColor-default" id="toggle-hash-algo">
          Create a SHA-256 repository
        </ControlGroup.Title>
        <ControlGroup.Description>
          If left unchecked, a default SHA-1 repository will be created. This option cannot be changed after creation.
        </ControlGroup.Description>
        <ControlGroup.ToggleSwitch
          aria-labelledby="toggle-hash-algo"
          checked={useSha256}
          onClick={e => {
            e.preventDefault()
            onUseSha256Change(!useSha256)
          }}
        />
      </ControlGroup.Item>
    </ControlGroup>
  )
}
