import {Checkbox, FormControl, Link} from '@primer/react'

import type {Team} from '../types/repo-creation-types'
import styles from './TeamListItem.module.css'

export function TeamListItem({
  team,
  selectedTeamIds,
  onChange,
}: {
  team: Team
  selectedTeamIds: string[]
  onChange: (s: string) => void
}) {
  return (
    <div className={styles.teamListItem} data-testid="team-list-item">
      <div className={styles.checkboxWrapper}>
        <FormControl>
          <Checkbox
            checked={selectedTeamIds.includes(team.id)}
            onChange={() => onChange(team.id)}
            value={team.name}
            aria-label={`Team ${team.name}`}
            data-testid="team-checkbox"
          />
          <FormControl.Label visuallyHidden>{team.name}</FormControl.Label>
        </FormControl>
      </div>
      <div className={styles.contentWrapper}>
        <strong>
          <Link href={team.path}>{team.name}</Link>
        </strong>
        <span className={styles.description}>{team.description}</span>
      </div>
      <span className={styles.memberCount}>{team.membersScopeCount}</span>
      <span>{team.repositoriesScopeCount}</span>
    </div>
  )
}
