import {UnsafeHTMLDiv} from '@github-ui/safe-html/UnsafeHTML'
import {Banner, Flash, Heading, Stack} from '@primer/react'
import {useEffect, useRef} from 'react'

export function RepoCreationForm({
  children,
  flash,
  title,
  description,
  submitButton,
  onSubmit,
  useModernHeader = false,
  shouldAutoFocusBanner = true,
}: {
  children: React.ReactNode
  flash: string
  title: string
  description: string | React.ReactNode
  submitButton?: React.ReactNode
  onSubmit?: () => void
  useModernHeader?: boolean
  shouldAutoFocusBanner?: boolean
}) {
  const flashRef = useRef<HTMLDivElement | null>(null)

  useEffect(() => {
    if (shouldAutoFocusBanner) {
      flashRef.current?.focus()
    }
  }, [flash, flashRef, shouldAutoFocusBanner])

  return (
    <form
      // By default HTML5 form will focus on the first required input with missing value on submit.
      // Although, this is fine for simple input fields it doesn't work nicely with custom inputs such as owner selector.
      // In result, it breaks our custom focus order.
      // This property disables default form behavior.
      noValidate
      onSubmit={e => {
        e.preventDefault()
        onSubmit?.()
      }}
      className={`container-md tmp-px-3 tmp-px-md-4 tmp-px-lg-5 my-${useModernHeader ? 4 : 6}`}
    >
      {!useModernHeader && flash && (
        <Flash
          tabIndex={0}
          ref={flashRef}
          data-testid="repo-creation-form-error-flash"
          variant="danger"
          className="mb-2"
        >
          <UnsafeHTMLDiv html={flash} />
        </Flash>
      )}
      <div>
        {useModernHeader ? (
          <Stack direction="horizontal" align="center">
            <Stack.Item>
              <Heading as="h1" variant="medium">
                {title}
              </Heading>
            </Stack.Item>
          </Stack>
        ) : (
          <Stack direction="horizontal" align="center">
            <Stack.Item>
              <Heading as="h1" className="f2">
                {title}
              </Heading>
            </Stack.Item>
          </Stack>
        )}
        <span className="fgColor-muted">{description}</span>
      </div>
      {!useModernHeader && <hr className="my-2" />}
      <div className={`text-italic${useModernHeader ? ' fgColor-muted' : ''}`}>
        Required fields are marked with an asterisk (*).
      </div>
      {useModernHeader && flash && (
        <Banner
          ref={flashRef}
          data-testid="repo-creation-form-error-banner"
          variant="critical"
          title="Error"
          hideTitle
          className="mt-2"
        >
          <Banner.Description>
            <UnsafeHTMLDiv html={flash} />
          </Banner.Description>
        </Banner>
      )}
      {children}
      <Stack direction="horizontal" justify="end">
        {submitButton}
      </Stack>
    </form>
  )
}
