import {useEffect, useMemo, useRef, useState} from 'react'

import {getRulesAllowedVisibilitiesForProposedRepository} from '../helpers/get-rules-allowed-visibilities-for-proposed-repository'
import {getDisplayedVisibilitiesWithRules, type VisibilityWithRestriction} from '../helpers/visibility'

interface UseRulesAwareVisibilitiesProps {
  ownerName: string | undefined
  isOrganization: boolean | undefined
  repositoryName: string
  displayedVisibilities: VisibilityWithRestriction[]
}

export function useRulesAwareVisibilities({
  ownerName,
  isOrganization,
  repositoryName,
  displayedVisibilities,
}: UseRulesAwareVisibilitiesProps): VisibilityWithRestriction[] {
  const [rulesAwareVisibilities, setRulesAwareVisibilities] = useState<{
    ownerName: string
    repositoryName: string
    visibilities: VisibilityWithRestriction[]
  } | null>(null)
  const previousOwnerNameRef = useRef(ownerName)

  const displayedVisibilitiesWithRules = useMemo(() => {
    if (
      !ownerName ||
      rulesAwareVisibilities?.ownerName !== ownerName ||
      rulesAwareVisibilities?.repositoryName !== repositoryName
    ) {
      return displayedVisibilities
    }

    return rulesAwareVisibilities.visibilities
  }, [displayedVisibilities, ownerName, repositoryName, rulesAwareVisibilities])

  useEffect(() => {
    const previousOwnerName = previousOwnerNameRef.current
    const currentOwnerName = ownerName
    const ownerChanged = previousOwnerName !== currentOwnerName
    previousOwnerNameRef.current = currentOwnerName

    if (!currentOwnerName || (!ownerChanged && !isOrganization)) {
      return
    }

    let canceled = false

    const timeoutId = setTimeout(async () => {
      const rulesAllowedVisibilities = await getRulesAllowedVisibilitiesForProposedRepository({
        owner: currentOwnerName,
        name: repositoryName,
      })

      if (canceled) {
        return
      }

      const visibilities = rulesAllowedVisibilities
        ? getDisplayedVisibilitiesWithRules({displayedVisibilities, rulesAllowedVisibilities})
        : displayedVisibilities

      setRulesAwareVisibilities({ownerName: currentOwnerName, repositoryName, visibilities})
    }, 300)

    return () => {
      canceled = true
      clearTimeout(timeoutId)
    }
  }, [displayedVisibilities, isOrganization, ownerName, repositoryName])

  return displayedVisibilitiesWithRules
}
