import type {OwnerItem} from '@github-ui/owner-dropdown'
import type {Visibility} from '@github-ui/repos-list'
import {Banner, Link} from '@primer/react'

import {InfoMessage} from './InfoMessage'

interface Props {
  owner?: OwnerItem
  topBorder?: boolean
  repoName?: string
}

interface CreateProps extends Props {
  visibility: Visibility
  action: 'create'
}

interface ForkProps extends Props {
  action: 'fork'
  helpUrl: string
}

function isCreateProps(props: CreateProps | ForkProps): props is CreateProps {
  return props.action === 'create'
}

export function CreationSummary(props: CreateProps | ForkProps) {
  const {owner, topBorder = false, repoName, action, ...rest} = props
  if (!owner) {
    return null
  }

  const {name, businessName, isOrganization} = owner
  const targetOrgName = isOrganization ? name : null
  const orgText = targetOrgName
    ? ` in the ${targetOrgName} organization${businessName ? ` (${businessName})` : ''}`
    : ' in your personal account'

  let message = ''
  let helpUrl = ''
  if (isCreateProps(props)) {
    const {visibility} = props
    message = `You are creating a${visibility === 'internal' ? 'n' : ''} ${visibility} repository${orgText}.`
  } else {
    helpUrl = (rest as ForkProps).helpUrl
    message = `You are creating a fork${orgText}.`
  }

  return (
    <>
      {repoName === '.github' && action === 'fork' && (
        <Banner
          variant="warning"
          title="Forking this .github repository affects default community health files"
          hideTitle
          className="tmp-mb-3 pb-0"
        >
          <Banner.Description>
            <p>
              <strong>This is a `.github` repository.</strong> Forking it will use this repository&apos;s{' '}
              <Link
                inline
                href={`${helpUrl}/communities/setting-up-your-project-for-healthy-contributions/creating-a-default-community-health-file`}
              >
                community health files
              </Link>{' '}
              as the publicly visible defaults for all repositories {orgText} that don&apos;t have their own. Review the
              contents of this repository before forking.
            </p>
          </Banner.Description>
        </Banner>
      )}
      <InfoMessage message={message} topBorder={topBorder} />
    </>
  )
}
